  const geometry=smoke?new THREE.SphereGeometry(size,7,6):new THREE.ConeGeometry(size,.28+Math.random()*.28,6,1);
  const palette=smoke?(intensity>1.15?['#1c211f','#303531','#454a45']:['#3c413c','#555a54','#676c65']):['#f04a20','#ff7528','#ffb23c','#ffd365'];
