  mesh.userData.effectParticle=kind;mesh.userData.life=smoke?1.2+Math.random()*.9:.28+Math.random()*.34;mesh.userData.maxLife=mesh.userData.life;mesh.userData.baseOpacity=material.opacity;mesh.userData.baseScale=1;
  mesh.userData.v=smoke?new THREE.Vector3((Math.random()-.5)*.34,.34+Math.random()*.40,(Math.random()-.5)*.34):new THREE.Vector3((Math.random()-.5)*.9,.5+Math.random()*.9,(Math.random()-.5)*.9);
