function modelPoint(root,model,key,fallback){
  const raw=model?.modules?.[key];
  if(model?.root&&Array.isArray(raw)){model.root.updateWorldMatrix(true,false);return model.root.localToWorld(new THREE.Vector3(raw[0],raw[1],raw[2]));}
  root.updateWorldMatrix(true,false);return root.localToWorld(new THREE.Vector3(...fallback));
}
function radiatorPoint(root,model,role='vehicle'){
  if(model?.modules?.radiator||model?.modules?.engine)return modelPoint(root,model,model.modules.radiator?'radiator':'engine',[0,.95,1.65]);
  // The simple range targets face -Z; the engine/radiator is at the back (+Z in model-local space).
  return modelPoint(root,null,'radiator',role==='target'?[0,.95,1.95]:[0,.95,1.65]);
}
