  state.cookoffStarted=true;state.cookoffRemaining=1.25;state.cookoffElapsed=0;state.turret=turret||state.turret;state.burning=true;root.userData.armorCookoffStarted=true;root.userData.armorWreckBurning=true;
  const p=roofFirePoint(root,model,[0,.10,0]);burst(p,'#ff8b35',effectsLevel==='high'?28:16);
