function updateVehicleEffectSystem(dt){
  const tick=(root,model,engineHealth,alive,reason,turret,role)=>{
    if(!root)return;const state=vehicleFxState(root,model,role);state.engineHealth=Number.isFinite(Number(engineHealth))?Number(engineHealth):100;state.engineDamaged=state.engineHealth<99.5;
    if(!alive){if(reason==='ammo')startAmmoCookoff(root,model,turret,role);else startVehicleBurning(root,model,turret,role);}
    if(state.engineDamaged&&alive){state.engineClock+=dt;const step=state.engineHealth<20?.14:state.engineHealth<50?.22:.40;if(state.engineClock>=step){state.engineClock=0;const at=radiatorPoint(root,model,role);emitVehicleParticle(at,'smoke',state.engineHealth<35?1.35:state.engineHealth<60?1.05:.8);if(state.engineHealth<15&&Math.random()<.24)emitVehicleParticle(at,'flame',.65);}}
    if(state.cookoffStarted&&!state.cookoffFinished){state.cookoffRemaining-=dt;state.cookoffElapsed+=dt;state.burnClock+=dt;state.smokeClock+=dt;if(state.burnClock>=.075){state.burnClock=0;emitVehicleParticle(roofFirePoint(root,model,[((Math.random()-.5)*1.1),Math.random()*.25,(Math.random()-.5)*.45]),'flame',1.1);}if(state.smokeClock>=.13){state.smokeClock=0;emitVehicleParticle(roofFirePoint(root,model,[0,.30,0]),'smoke',1.55);}if(state.cookoffRemaining<=0){const blastAt=state.turret?state.turret.getWorldPosition(new THREE.Vector3()):roofFirePoint(root,model,[0,.4,0]);spawnAmmoExplosion(blastAt);if(state.turret)ejectTurretVisual(state.turret,root);state.cookoffFinished=true;state.cookoffRemaining=0;state.burnClock=0;state.smokeClock=0;}}
    if(state.burning){state.burnClock+=dt;state.smokeClock+=dt;if(state.burnClock>=.13){state.burnClock=0;emitVehicleParticle(roofFirePoint(root,model,[((Math.random()-.5)*1.35),Math.random()*.25,(Math.random()-.5)*.8]),'flame',.95+Math.random()*.45);}if(state.smokeClock>=.21){state.smokeClock=0;emitVehicleParticle(roofFirePoint(root,model,[0,.32,0]),'smoke',1.4);const back=radiatorPoint(root,model,role);emitVehicleParticle(back,'smoke',1.15);}}
  };
  // Player's tank: damage can be local practice damage or received from the server.
  tick(tank,activeVehicleModel,modules.engine,(!netSelfId||netAlive),netSelfId&&!netAlive?(modules.ammo<=0?'ammo':'crew'):null,activeVehicleModel?.turret,'player');
  for(const t of targets)tick(t.group,null,t.engine,t.alive,t.fatalReason,t.botTurret,'target');
  for(const e of remotePlayers.values())tick(e.group,e.model,e.state?.modules?.engine??100,e.state?.alive!==false,e.state?.fatalReason,e.model?.turret,'remote');
}
