let dragging=false,lastX=0,lastY=0,dragStartX=0,dragStartY=0,cameraOrbitMode=false;const editorRaycaster=new THREE.Raycaster(),editorMouse=new THREE.Vector2();canvas.addEventListener('contextmenu',e=>e.preventDefault());
