 document.querySelector('#xrSub').textContent=penetrates?'Подсвечена условная зона, затронутая попаданием. Остальные узлы не повреждаются автоматически.':'Попадание остановлено внешней бронёй; внутренние модули не затронуты.';
 ['Crew','Ammo','Engine','Track'].forEach(k=>{const el=document.querySelector('#xr'+k);el.setAttribute('fill',k.toLowerCase()===zone?'#ed785e':({'Crew':'#8b9d76','Ammo':'#b5a16a','Engine':'#697d60','Track':'#242c24'}[k]));el.setAttribute('stroke',k.toLowerCase()===zone?'#fff0c9':'none');el.setAttribute('stroke-width','2')});
 const pos={crew:[99,24],ammo:[94,43],engine:[145,46],track:[100,54],gun:[104,17],optics:[130,20],outer:[35,31]}[zone]||[35,31];document.querySelector('#xrHit').setAttribute('cx',pos[0]);document.querySelector('#xrHit').setAttribute('cy',pos[1]);
