// Ballistic, game-only projectile model inspired by vehicle-builder sims: travel time, gravity, drag, impact angle, ricochet and per-part armor values.
const liveProjectiles=[];
const armorByZone={hull:135,turret:165,track:22};
function getGameArmor(hitObject,impactAngle){
 const zone=hitObject?.userData?.zone||'hull';
 const nominal=armorByZone[zone]||80;
 // Angle is measured from the plate normal: grazing hits get more effective thickness.
 const cos=Math.max(.16,Math.cos(THREE.MathUtils.degToRad(Math.min(impactAngle,80))));
 return {zone,nominal,effective:nominal/cos};
}
function spawnProjectile(){
 if(modules.gun<=0){notify('Орудие выведено из строя · выстрел невозможен');return;}
 if(netSocket&&netSocket.readyState===WebSocket.OPEN&&netSelfId&&!netAlive){notify('Танк уничтожен · возродись перед выстрелом');return;}
 if(reloading||shotCooldown>0)return;
 if(shells<=0){notify('Боекомплект пуст');return}
 shells--;shotsFired++;shotCooldown=.25;playSound(95,.24,'sawtooth',.055);updateHUD();updateScore();
 tank.updateMatrixWorld(true);const origin=muzzle.getWorldPosition(new THREE.Vector3());
 const dir=new THREE.Vector3(0,0,-1).applyQuaternion(gunPivot.getWorldQuaternion(new THREE.Quaternion())).normalize();
 const shell=shellTypes[shellType];const speed=shellType===0?105:shellType===1?82:58;
 const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.42,7),new THREE.MeshBasicMaterial({color:shellType===2?'#d5a76c':'#e9d5a1'}));
 mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),dir);mesh.position.copy(origin);scene.add(mesh);
 const tracer=new THREE.Mesh(new THREE.SphereGeometry(.055,6,5),new THREE.MeshBasicMaterial({color:'#ffcf82'}));tracer.position.copy(origin);scene.add(tracer);
 const shotVelocity=dir.clone().multiplyScalar(speed);const networkProjectileId=netSocket&&netSocket.readyState===WebSocket.OPEN&&netSelfId?`${netSelfId}:${++netShotSeq}`:null;liveProjectiles.push({mesh,tracer,pos:origin.clone(),vel:shotVelocity,life:5,shellType,penetration:shell.penetration*shell.energy,previous:origin.clone(),networkProjectileId,remoteOnly:false});if(networkProjectileId)netSend({type:'fire',projectileId:networkProjectileId,origin:origin.toArray(),direction:dir.clone().normalize().toArray(),shellType});
 burst(origin,'#ffdb8a',effectsLevel==='high'?14:7);const flash=new THREE.PointLight('#ffbb71',12,9);flash.position.copy(origin);scene.add(flash);setTimeout(()=>scene.remove(flash),70);
 document.querySelector('#lastResult').textContent='СНАРЯД В ПОЛЁТЕ';document.querySelector('#lastResult').style.color='#e9d5a1';
 if(shells>0){reloading=true;reloadRemaining=tankReloadSeconds[selectedTank]||5.8;notify('Перезарядка · '+reloadRemaining.toFixed(1)+' с');}else{reloading=false;reloadRemaining=0;notify('Боекомплект израсходован');}
}
function moduleForBotHit(target,meshZone,point){
 const local=target.group.worldToLocal(point.clone());
 if(meshZone==='track')return 'track';
 if(meshZone==='turret'){
  const q=target.botTurret.worldToLocal(point.clone());
  // The rear half of the turret is a deliberately generous, aimable ammo-rack zone.
  if(q.z>-0.25)return 'ammo';
  if(q.y>.78&&Math.abs(q.x)>.52&&q.z<0)return 'optics';
  if(Math.abs(q.x)<.58&&q.y>.30)return 'crew';
  return 'gun';
 }
 if(local.y>1.10&&Math.abs(local.x)<.78&&local.z>.05&&local.z<1.22)return 'ammo';
 if(local.z>1.22)return 'engine';
 if(local.y>.92&&Math.abs(local.x)<.82)return 'crew';
 if(local.z<-.9&&local.y>.7)return 'crew';
 return 'engine';
}
function destroyBotTarget(target,reason,point){
 if(!target.alive)return;target.alive=false;target.hp=0;target.fatalReason=reason;target.group.rotation.z=.35;target.group.position.y=-.08;
 if(reason==='ammo'){
  startAmmoCookoff(target.group,null,target.botTurret,'target');
  notify('БОЕКОМПЛЕКТ ВОСПЛАМЕНИЛСЯ · ДЕТОНАЦИЯ ЧЕРЕЗ МГНОВЕНИЕ');
 }else {startVehicleBurning(target.group,null,target.botTurret,'target');notify('ЭКИПАЖ ПОТЕРЯН · МАШИНА ГОРИТ');}
}
function resolveProjectileImpact(hit,projectile,dir){
 const obj=hit.object,point=hit.point.clone();
 const target=targets.find(t=>{let found=false;t.group.traverse(o=>{if(o===obj)found=true});return found});
 const remoteEntry=[...remotePlayers.values()].find(r=>{let found=false;r.group.traverse(o=>{if(o===obj)found=true});return found});
 if(remoteEntry&&!projectile.remoteOnly){resolveRemotePlayerImpact(hit,projectile,dir,remoteEntry);return;}
 if(projectile.remoteOnly){if(obj.userData.netLocalHitZone)resolveIncomingPlayerImpact(hit,projectile,dir);else if(projectile.networkProjectileId)netSend({type:'impact',projectileId:projectile.networkProjectileId});return;}
 if(!target&&(obj.userData.cover||mapObjects.includes(obj))){if(projectile.networkProjectileId)netSend({type:'impact',projectileId:projectile.networkProjectileId,coverId:obj.userData.cover?obj.userData.coverId:null});if(obj.userData.cover){scene.remove(obj);coverObjects=coverObjects.filter(o=>o!==obj);obj.geometry?.dispose();obj.material?.dispose();score+=5;updateScore();notify('Укрытие разрушено')}else{notify('Снаряд остановлен препятствием')}burst(point,'#b6a17b',effectsLevel==='high'?30:16);playSound(180,.12,'triangle',.025);document.querySelector('#lastResult').textContent=obj.userData.cover?'УКРЫТИЕ РАЗРУШЕНО':'ПРЕПЯТСТВИЕ';return;}
 if(!target)return;
 shotsHit++;score+=10;updateScore();hitHistory.unshift({name:target.botName||'ЦЕЛЬ',time:new Date().toLocaleTimeString(),zone:obj.userData.zone||'корпус'});if(hitHistory.length>12)hitHistory.pop();
 const normal=hit.face?hit.face.normal.clone().transformDirection(obj.matrixWorld).normalize():new THREE.Vector3(0,1,0);
 const angle=Math.acos(THREE.MathUtils.clamp(Math.abs(dir.dot(normal)),0,1))*180/Math.PI;
 const armor=getGameArmor(obj,angle);const ricochet=angle>72&&projectile.shellType!==2;const penetrates=!ricochet&&projectile.penetration>armor.effective;
 document.querySelector('#angle').textContent=Math.round(angle)+'°';document.querySelector('#armorValue').textContent=Math.round(armor.effective)+' мм*';
 addImpactMark(point,normal,penetrates,target.group,obj);burst(point,penetrates?'#ffb96b':'#d8d5a5',penetrates?24:12);playSound(penetrates?155:230,.09,'triangle',.03);
 let moduleName='outer';
 if(penetrates){
  moduleName=moduleForBotHit(target,armor.zone,point);
  const damage=projectile.shellType===2?32:({ammo:100,crew:55,engine:62,track:100,gun:68,optics:70}[moduleName]||40);
  if(moduleName==='ammo')target.ammo=0;
  else if(moduleName==='crew')target.crew=Math.max(0,target.crew-damage);
  else if(moduleName==='engine')target.engine=Math.max(0,target.engine-damage);
  else if(moduleName==='track')target.track=Math.max(0,target.track-damage);
  else if(moduleName==='gun')target.gun=Math.max(0,(target.gun??100)-damage);
  else if(moduleName==='optics')target.optics=Math.max(0,(target.optics??100)-damage);
  const labels={ammo:'боекомплект — критическое попадание',crew:'экипаж',engine:'двигатель',track:'ходовая часть',gun:'привод орудия',optics:'приборы'};
  document.querySelector('#lastResult').textContent=moduleName==='ammo'?'БК ВЗОРВАН':'ПРОБИТИЕ · '+(labels[moduleName]||'модуль');document.querySelector('#lastResult').style.color='#b7d87b';showHitXray(moduleName,true,labels[moduleName]||'модуль');
  if(target.ammo<=0)destroyBotTarget(target,'ammo',point);
  else if(target.crew<=0)destroyBotTarget(target,'crew',point);
  else if(target.track<=0)notify('ХОДОВАЯ УНИЧТОЖЕНА · ЦЕЛЬ ОБЕЗДВИЖЕНА');
  else if(target.engine<=0)notify('ДВИГАТЕЛЬ ВЫВЕДЕН ИЗ СТРОЯ');
  else if(target.gun<=0)notify('ПРИВОД ОРУДИЯ УНИЧТОЖЕН');
  else notify('Пробитие: '+(labels[moduleName]||'модуль'));
 }else{
  // Explosive rounds may damage exposed tracks/optics; they do not subtract a generic vehicle HP pool.
  if(projectile.shellType===2&&armor.zone==='track'){target.track=Math.max(0,target.track-45);if(target.track<=0)notify('ХОДОВАЯ ПОВРЕЖДЕНА');}
  document.querySelector('#lastResult').textContent=ricochet?'РИКОШЕТ':'НЕ ПРОБИЛ';document.querySelector('#lastResult').style.color='#ffbd70';showHitXray('outer',false,ricochet?'снаряд срикошетил':`броня ${armor.nominal} мм остановила попадание`);if(ricochet)notify('Рикошет — слишком острый угол');else notify('Броня не пробита');
 }
 if(projectile.networkProjectileId)netSend({type:'impact',projectileId:projectile.networkProjectileId});
 document.querySelector('#hitmarker').style.opacity='1';setTimeout(()=>document.querySelector('#hitmarker').style.opacity='0',220);openComponents(false);
}
function updateProjectiles(dt){
 const baseHittables=[];targets.filter(t=>t.alive).forEach(t=>t.group.traverse(o=>{if(o.isMesh&&o.userData.hitCollider)baseHittables.push(o)}));coverObjects.forEach(o=>baseHittables.push(o));mapObjects.forEach(o=>{if(o.userData.solid!==false)baseHittables.push(o)});
 const remoteColliders=[];for(const r of remotePlayers.values())if(r.state?.alive!==false)r.group.traverse(o=>{if(o.isMesh&&o.userData.netHitCollider)remoteColliders.push(o)});
 const localColliders=[];tank.traverse(o=>{if(o.isMesh&&o.userData.netLocalHitZone)localColliders.push(o)});
 for(let i=liveProjectiles.length-1;i>=0;i--){const p=liveProjectiles[i];p.life-=dt;p.previous.copy(p.pos);p.vel.y-=9.81*dt;p.vel.multiplyScalar(1-.008*dt);p.pos.addScaledVector(p.vel,dt);
  const segment=p.pos.clone().sub(p.previous),distance=segment.length();let hit=null;
  if(distance>0){const rc=new THREE.Raycaster(p.previous,segment.clone().normalize(),0,distance);const list=p.remoteOnly?[...coverObjects,...mapObjects.filter(o=>o.userData.solid!==false),...localColliders]:[...baseHittables,...remoteColliders];const hits=rc.intersectObjects(list,false);if(hits.length)hit=hits[0];}
  p.mesh.position.copy(p.pos);p.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),p.vel.clone().normalize());p.tracer.position.copy(p.pos);
  if(hit){resolveProjectileImpact(hit,p,p.vel.clone().normalize());scene.remove(p.mesh,p.tracer);p.mesh.geometry.dispose();p.mesh.material.dispose();p.tracer.geometry.dispose();p.tracer.material.dispose();liveProjectiles.splice(i,1)}else if(p.life<=0||p.pos.y<-.5||p.pos.distanceTo(p.previous)>30){scene.remove(p.mesh,p.tracer);p.mesh.geometry.dispose();p.mesh.material.dispose();p.tracer.geometry.dispose();p.tracer.material.dispose();liveProjectiles.splice(i,1)}
 }
}

