function moduleForLocalPlayerHit(zone,point){if(zone==='track')return 'track';const local=tank.worldToLocal(point.clone());if(zone==='turret'&&turret){const tq=turret.worldToLocal(point.clone());if(tq.z>-.25)return 'ammo';if(tq.y>.78&&Math.abs(tq.x)>.52&&tq.z<0)return 'optics';if(Math.abs(tq.x)<.58&&tq.y>.30)return 'crew';return 'gun';}if(local.y>1.10&&Math.abs(local.x)<.78&&local.z>.05&&local.z<1.22)return 'ammo';if(selectedTank==='merkava'?local.z< -1.2:local.z>1.22)return 'engine';if(local.y>.92&&Math.abs(local.x)<.82)return 'crew';return 'engine';}

