function beginNetworkDeath(respawnIn=8,reason=null){netAlive=false;velocity=0;steeringResponse=0;if(reason==='ammo')startAmmoCookoff(tank,activeVehicleModel,activeVehicleModel?.turret,'player');else startVehicleBurning(tank,activeVehicleModel,activeVehicleModel?.turret,'player');const parsed=Number(respawnIn);const secs=Math.max(0,Number.isFinite(parsed)?parsed:8);netRespawnAtClientMs=Date.now()+secs*1000;tank.rotation.z=.42;document.querySelector('#condition').textContent='УНИЧТОЖЕН · ВОЗРОЖДЕНИЕ';const overlay=document.querySelector('#netDeathOverlay');if(overlay)overlay.classList.add('show');updateNetworkDeathUI();}
function updateNetworkDeathUI(){const overlay=document.querySelector('#netDeathOverlay');if(!overlay)return;if(!netSelfId||netAlive){overlay.classList.remove('show');return;}overlay.classList.add('show');const seconds=Math.max(0,Math.ceil((netRespawnAtClientMs-Date.now())/1000));const label=document.querySelector('#netRespawnCountdown');if(label)label.textContent=seconds>0?'Возрождение через '+seconds+' сек.':'Возрождение…';const btn=document.querySelector('#respawnBtn');if(btn&&netSocket&&netSocket.readyState===WebSocket.OPEN)btn.textContent=seconds>0?'ВОЗРОЖДЕНИЕ ('+seconds+')':'ВОЗРОДИТЬСЯ';}
function clearNetworkDeath(){netAlive=true;netRespawnAtClientMs=0;document.querySelector('#netDeathOverlay')?.classList.remove('show');const btn=document.querySelector('#respawnBtn');if(btn)btn.textContent='ВОЗРОДИТЬ ИГРОКА';}
function applyDeadVisual(entry,state){entry.group.visible=true;const wasDestroyed=entry.state?.alive===false||Number(entry.state?.health)<=0;const destroyed=state.alive===false||Number(state.health)<=0;entry.group.rotation.z=destroyed?.42:0;entry.state={...entry.state,...state};entry.target={...entry.target,...state};if(destroyed){if(state.fatalReason==='ammo')startAmmoCookoff(entry.group,entry.model,entry.model?.turret,'remote');else startVehicleBurning(entry.group,entry.model,entry.model?.turret,'remote');}if(!destroyed&&state.alive===true&&wasDestroyed){clearVehicleEffects(entry.group);clearImpactMarksForRoot(entry.group);clearDetachedTurretForRoot(entry.group);if(entry.model?.turret){entry.model.turret.visible=true;entry.model.turret.userData.detachedOnce=false;}}}

function netNameSprite(name,team){const c=document.createElement('canvas');c.width=512;c.height=96;const ctx=c.getContext('2d');ctx.fillStyle=team==='red'?'rgba(70,20,15,.82)':'rgba(12,35,35,.82)';ctx.beginPath();ctx.roundRect(4,8,504,80,18);ctx.fill();ctx.strokeStyle=team==='red'?'#ef8a72':'#91cfdf';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle='#f3f2e7';ctx.font='bold 38px system-ui, sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(String(name||'Tanker').slice(0,24),256,49);const texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;const sprite=new THREE.Sprite(new THREE.SpriteMaterial({map:texture,transparent:true,depthWrite:false,depthTest:false}));sprite.scale.set(3.7,.7,1);sprite.position.set(0,4.05,0);sprite.userData.netNameTexture=texture;return sprite;}
function cleanupRemote(entry){scene.remove(entry.group);entry.group.traverse(o=>{if(o.isMesh){o.geometry?.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material?.dispose();}if(o.isSprite&&o.userData.netNameTexture)o.userData.netNameTexture.dispose();});}
function makeRemotePlayer(state){const group=new THREE.Group();group.name='network-player-'+state.id;group.scale.copy(tank.scale);const model=(vehicleFactories[state.tank]||createT90)(THREE,mat);model.root.name='network-model-'+state.tank;group.add(model.root);const colliderMat=new THREE.MeshBasicMaterial({transparent:true,opacity:0,depthWrite:false});const box=(w,h,d,pos,zone,parent=group)=>{const c=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),colliderMat);c.position.set(...pos);c.userData.netHitCollider=true;c.userData.hitCollider=true;c.userData.zone=zone;parent.add(c);return c;};box(3.35,1.22,5.25,[0,.95,0],'hull');box(.55,.9,5.1,[-1.63,.72,0],'track');box(.55,.9,5.1,[1.63,.72,0],'track');box(2.35,1.12,2.95,[0,.53,0],'turret',model.turret);const label=netNameSprite(state.nickname,state.team);group.add(label);scene.add(group);const entry={id:state.id,group,model,tankType:state.tank,state:{...state},target:{...state},label,nickname:state.nickname,team:state.team};remotePlayers.set(state.id,entry);applyRemoteTransform(entry,state,true);return entry;}
function rebuildRemoteModel(entry,type){const old=entry.model;for(const c of entry.group.children.filter(o=>o.userData?.netModelCollider&&o.userData.zone==='turret'))entry.group.remove(c);old.root.traverse(o=>{if(o.isMesh){o.geometry?.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material?.dispose();}});entry.group.remove(old.root);entry.model=(vehicleFactories[type]||createT90)(THREE,mat);entry.model.root.name='network-model-'+type;entry.group.add(entry.model.root);const c=new THREE.Mesh(new THREE.BoxGeometry(2.35,1.12,2.95),netLocalColliderMat.clone());c.position.set(0,.53,0);c.userData.netHitCollider=true;c.userData.netModelCollider=true;c.userData.hitCollider=true;c.userData.zone='turret';entry.model.turret.add(c);entry.tankType=type;}
function applyRemoteTransform(entry,state,immediate=false){if(state.tank&&state.tank!==entry.tankType)rebuildRemoteModel(entry,state.tank);entry.target={...entry.target,...state};if(immediate){entry.group.position.set(Number(state.x)||0,Number(state.y)||0,Number(state.z)||0);entry.group.rotation.y=Number(state.yaw)||0;entry.model.turret.rotation.y=Number(state.turretYaw)||0;entry.model.gun.rotation.x=Number(state.gunPitch)||0;}if(entry.label&&state.nickname&&(entry.nickname!==state.nickname||entry.team!==state.team)){entry.nickname=state.nickname;entry.team=state.team;const old=entry.label,newer=netNameSprite(state.nickname,state.team);entry.group.remove(old);old.material.map?.dispose();old.material.dispose();entry.group.add(newer);entry.label=newer;}}
function updateNetRoster(players){const el=document.querySelector('#netRoster');if(!el)return;el.innerHTML='';const sorted=(players||[]).slice().sort((a,b)=>String(a.nickname).localeCompare(String(b.nickname)));for(const p of sorted){const row=document.createElement('div');row.className='net-player';const dot=document.createElement('i');dot.className='net-dot';dot.style.background=p.team==='red'?'#ef785e':'#81c6df';const name=document.createElement('span');name.textContent=p.nickname+(p.id===netSelfId?' (ты)':'');const team=document.createElement('span');team.className='net-player-team';team.textContent=p.team==='red'?'КРАСНЫЕ':'СИНИЕ';const model=document.createElement('span');model.className='net-player-tank';model.textContent=({t90:'Т-90М',abrams:'Abrams',leopard:'Leopard 2A7',merkava:'Merkava'}[p.tank]||p.tank||'Танк');row.append(dot,name,team,model);el.appendChild(row);}document.querySelector('#netPlayersInfo').textContent='Игроков: '+(players||[]).length;if(!players?.length)el.innerHTML='<span class="muted">Пока нет подключённых игроков.</span>';}
function applyNetworkRoster(players){const seen=new Set();for(const st of players||[]){if(!st?.id||st.id===netSelfId)continue;seen.add(st.id);let e=remotePlayers.get(st.id);if(!e)e=makeRemotePlayer(st);applyRemoteTransform(e,st,false);applyDeadVisual(e,st);}for(const [id,e] of remotePlayers){if(!seen.has(id)){cleanupRemote(e);remotePlayers.delete(id);}}updateNetRoster(players||[]);}
function setNetStatus(text){const el=document.querySelector('#netStatus');if(el)el.textContent=text;}
function makeNetworkProjectile(msg){if(!Array.isArray(msg.origin)||!Array.isArray(msg.direction))return;const shellType=THREE.MathUtils.clamp(Number(msg.shellType)||0,0,2)|0;const direction=new THREE.Vector3(...msg.direction).normalize();const origin=new THREE.Vector3(...msg.origin);const shell=new THREE.Mesh(new THREE.CylinderGeometry(.035,.035,.42,7),new THREE.MeshBasicMaterial({color:shellType===2?'#d5a76c':'#e9d5a1'}));shell.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),direction);shell.position.copy(origin);scene.add(shell);const tracer=new THREE.Mesh(new THREE.SphereGeometry(.055,6,5),new THREE.MeshBasicMaterial({color:'#ffcf82'}));tracer.position.copy(origin);scene.add(tracer);const speed=shellType===0?105:shellType===1?82:58;liveProjectiles.push({mesh:shell,tracer,pos:origin,vel:direction.multiplyScalar(speed),life:5,shellType,penetration:shellTypes[shellType].penetration*shellTypes[shellType].energy,previous:origin.clone(),networkProjectileId:msg.projectileId,remoteOnly:true,shooterId:msg.id});burst(origin,'#ffdb8a',5);}
function moduleForNetworkHit(zone,entry,point){if(zone==='track')return 'track';const local=entry.group.worldToLocal(point.clone());if(zone==='turret'&&entry.model?.turret){const tq=entry.model.turret.worldToLocal(point.clone());if(tq.z>-.25)return 'ammo';if(tq.y>.78&&Math.abs(tq.x)>.52&&tq.z<0)return 'optics';if(Math.abs(tq.x)<.58&&tq.y>.30)return 'crew';return 'gun';}if(local.y>1.10&&Math.abs(local.x)<.78&&local.z>.05&&local.z<1.22)return 'ammo';if(entry.tankType==='merkava'?local.z< -1.2:local.z>1.22)return 'engine';if(local.y>.92&&Math.abs(local.x)<.82)return 'crew';return 'engine';}
function resolveRemotePlayerImpact(hit,projectile,dir,entry){const obj=hit.object,point=hit.point.clone(),normal=hit.face?hit.face.normal.clone().transformDirection(obj.matrixWorld).normalize():new THREE.Vector3(0,1,0),angle=Math.acos(THREE.MathUtils.clamp(Math.abs(dir.dot(normal)),0,1))*180/Math.PI,zone=obj.userData.zone||'hull',armor=getGameArmor(obj,angle),ricochet=angle>72&&projectile.shellType!==2,penetrates=!ricochet&&projectile.penetration>armor.effective,module=penetrates?moduleForNetworkHit(zone,entry,point):'engine';addImpactMark(point,normal,penetrates,entry.group,obj);burst(point,penetrates?'#ffb96b':'#d8d5a5',penetrates?20:10);playSound(penetrates?155:230,.09,'triangle',.03);document.querySelector('#lastResult').textContent=penetrates?'ПОПАДАНИЕ В ИГРОКА':'РИКОШЕТ / НЕПРОБИТИЕ';document.querySelector('#lastResult').style.color=penetrates?'#b7d87b':'#ffbd70';showHitXray(penetrates?module:'outer',penetrates,penetrates?'сетевое попадание':'броня остановила попадание');if(projectile.networkProjectileId)netSend({type:'hit',projectileId:projectile.networkProjectileId,targetId:entry.id,module,penetrates,point:point.toArray()});document.querySelector('#hitmarker').style.opacity='1';setTimeout(()=>document.querySelector('#hitmarker').style.opacity='0',220);}
function resolveIncomingPlayerImpact(hit,projectile,dir){const obj=hit.object,point=hit.point.clone(),normal=hit.face?hit.face.normal.clone().transformDirection(obj.matrixWorld).normalize():new THREE.Vector3(0,1,0),zone=obj.userData.netLocalHitZone||'hull',angle=Math.acos(THREE.MathUtils.clamp(Math.abs(dir.dot(normal)),0,1))*180/Math.PI,armor=getGameArmor(obj,angle),ricochet=angle>72&&projectile.shellType!==2,penetrates=!ricochet&&projectile.penetration>armor.effective,module=penetrates?moduleForLocalPlayerHit(zone,point):'engine';addImpactMark(point,normal,penetrates,tank,obj);burst(point,penetrates?'#ff8059':'#d8d5a5',penetrates?18:8);document.querySelector('#lastResult').textContent=penetrates?'ПОПАДАНИЕ · '+module:'РИКОШЕТ / НЕПРОБИТИЕ';showHitXray(penetrates?module:'outer',penetrates,penetrates?'сетевое попадание':'броня остановила попадание');if(projectile.networkProjectileId)netSend({type:'hit',projectileId:projectile.networkProjectileId,targetId:netSelfId,module,penetrates,point:point.toArray()});}
function removeNetProjectile(id){for(let i=liveProjectiles.length-1;i>=0;i--){const p=liveProjectiles[i];if(p.networkProjectileId===id){scene.remove(p.mesh,p.tracer);p.mesh.geometry.dispose();p.mesh.material.dispose();p.tracer.geometry.dispose();p.tracer.material.dispose();liveProjectiles.splice(i,1);}}}
function applyNetworkDamage(msg){
 if(msg.targetId===netSelfId){
  if(msg.modules)Object.entries(msg.modules).forEach(([k,v])=>{if(k in modules)setModule(k,v)});
  if(msg.turretEjected||msg.fatalReason==='ammo')startAmmoCookoff(tank,activeVehicleModel,activeVehicleModel?.turret,'player');
  if(msg.health<=0||msg.alive===false){if(netAlive)notify(msg.fatalReason==='ammo'?'БК загорелся · детонация и срыв башни':'Танк уничтожен · машина горит');if(msg.fatalReason!=='ammo')startVehicleBurning(tank,activeVehicleModel,activeVehicleModel?.turret,'player');beginNetworkDeath(msg.respawnIn??8,msg.fatalReason);}
  else if(msg.penetrates){document.querySelector('#condition').textContent='ПОВРЕЖДЁН';const names={engine:'двигатель',track:'ходовая',gun:'привод орудия',optics:'оптика',ammo:'боекомплект',crew:'экипаж'};notify('Пробитие: '+(names[msg.module]||msg.module)+(msg.loss?' · модуль −'+msg.loss+'%':''));}
  updateHUD();
 }else{
  const e=remotePlayers.get(msg.targetId);if(e){e.state.health=msg.health;e.state.alive=msg.alive;e.state.modules=msg.modules;e.state.respawnAt=msg.respawnAt;e.state.respawnIn=msg.respawnIn;e.state.fatalReason=msg.fatalReason;
   if(msg.turretEjected||msg.fatalReason==='ammo')startAmmoCookoff(e.group,e.model,e.model?.turret,'remote');
   if(msg.health<=0||msg.alive===false){if(msg.fatalReason!=='ammo')startVehicleBurning(e.group,e.model,e.model?.turret,'remote');e.group.rotation.z=.42;notify('Уничтожен игрок '+(e.nickname||''));}
   applyDeadVisual(e,e.state);
  }
 }
 removeNetProjectile(msg.projectileId);
}
function updateMultiplayer(dt){if(!netSocket||netSocket.readyState!==WebSocket.OPEN||!netSelfId)return;netSendClock+=dt;if(netSendClock>=.05){netSendClock=0;if(netAlive)netSend({type:'state',x:tank.position.x,y:tank.position.y,z:tank.position.z,yaw:tank.rotation.y,turretYaw:turret?.rotation.y||0,gunPitch:gunPivot?.rotation.x||0,velocity,tank:selectedTank});}for(const e of remotePlayers.values()){const t=e.target;e.group.position.x=THREE.MathUtils.damp(e.group.position.x,Number(t.x)||0,13,dt);e.group.position.y=THREE.MathUtils.damp(e.group.position.y,Number(t.y)||0,13,dt);e.group.position.z=THREE.MathUtils.damp(e.group.position.z,Number(t.z)||0,13,dt);const yawDelta=THREE.MathUtils.euclideanModulo((Number(t.yaw)||0)-e.group.rotation.y+Math.PI,Math.PI*2)-Math.PI;e.group.rotation.y+=yawDelta*Math.min(1,dt*13);const ty=Number(t.turretYaw)||0,dy=THREE.MathUtils.euclideanModulo(ty-e.model.turret.rotation.y+Math.PI,Math.PI*2)-Math.PI;e.model.turret.rotation.y+=dy*Math.min(1,dt*15);e.model.gun.rotation.x=THREE.MathUtils.damp(e.model.gun.rotation.x,Number(t.gunPitch)||0,15,dt);}}
function handleNetworkMessage(msg){
 if(msg.type==='welcome'){netSelfId=msg.id;netRoomCode=msg.room;netAlive=true;netHostId=msg.hostId||null;applyRoomState(msg,false);const me=msg.player;if(me){tank.position.set(me.x||0,me.y||0,me.z||0);tank.rotation.y=me.yaw||0;if(me.alive===false){if(me.fatalReason==='ammo')startAmmoCookoff(tank,activeVehicleModel,activeVehicleModel?.turret,'player');else startVehicleBurning(tank,activeVehicleModel,activeVehicleModel?.turret,'player');beginNetworkDeath(me.respawnIn??8,me.fatalReason);}else clearNetworkDeath();}setNetStatus('В КОМНАТЕ '+netRoomCode+(netSelfId===netHostId?' · СОЗДАТЕЛЬ':''));applyNetworkRoster(msg.players||[]);notify('Подключено к комнате '+netRoomCode+' · карта синхронизирована');return;}
 if(msg.type==='map_changed'){applyRoomState(msg,!!msg.startRound);setNetStatus('В КОМНАТЕ '+netRoomCode+(netSelfId===netHostId?' · СОЗДАТЕЛЬ':''));notify('Все игроки перешли на карту: '+({range:'Учебный полигон',desert:'Пустыня',dusk:'Сумерки'}[msg.map]||msg.map));return;}
 if(msg.type==='room_config'){applyRoomState(msg,false);setNetStatus('В КОМНАТЕ '+netRoomCode+(netSelfId===netHostId?' · СОЗДАТЕЛЬ':''));return;}
 if(msg.type==='snapshot'||msg.type==='roster'){if(msg.map&&((msg.map!==appliedRoomMap)||(Number(msg.mapSeed)!==Number(appliedRoomMapSeed))))applyRoomState(msg,false);else if(msg.hostId&&msg.hostId!==netHostId){netHostId=msg.hostId;updateMapAuthority();}applyNetworkRoster(msg.players||[]);return;}
 if(msg.type==='player_joined'){if(msg.hostId){netHostId=msg.hostId;updateMapAuthority();}if(msg.player)notify(msg.player.nickname+' вошёл в комнату');applyNetworkRoster(msg.players||[]);return;}
 if(msg.type==='player_left'){if(msg.hostId){netHostId=msg.hostId;updateMapAuthority();}notify((msg.nickname||'Игрок')+' покинул комнату');applyNetworkRoster(msg.players||[]);return;}
 if(msg.type==='fire'){makeNetworkProjectile(msg);return;}
 if(msg.type==='impact'){removeNetProjectile(msg.projectileId);if(msg.coverId)removeSynchronizedCover(msg.coverId);return;}
 if(msg.type==='damage'){applyNetworkDamage(msg);return;}
 if(msg.type==='respawned'&&msg.player){const p=msg.player;clearVehicleEffects(tank);clearImpactMarksForRoot(tank);clearDetachedTurretForRoot(tank);if(activeVehicleModel?.turret){activeVehicleModel.turret.visible=true;activeVehicleModel.turret.userData.detachedOnce=false;}tank.position.set(p.x||0,p.y||0,p.z||0);tank.rotation.y=p.yaw||0;velocity=0;steeringResponse=0;clearNetworkDeath();tank.rotation.z=0;Object.entries(p.modules||{}).forEach(([k,v])=>{if(k in modules)setModule(k,v)});shells=24;reloading=false;reloadRemaining=0;shotCooldown=0;document.querySelector('#condition').textContent='БОЕГОТОВ';updateHUD();notify('Сетевое возрождение: новая точка, БК пополнен');return;}
 if(msg.type==='player_respawned'&&msg.player){const p=msg.player;if(p.id===netSelfId)return;let e=remotePlayers.get(p.id);if(!e)e=makeRemotePlayer(p);clearVehicleEffects(e.group);clearImpactMarksForRoot(e.group);clearDetachedTurretForRoot(e.group);if(e.model?.turret){e.model.turret.visible=true;e.model.turret.userData.detachedOnce=false;}applyRemoteTransform(e,p,true);e.group.rotation.z=0;e.group.visible=true;e.state={...p};e.target={...p};applyNetworkRoster([...(Array.from(remotePlayers.values()).map(e=>e.state)),p]);return;}
 if(msg.type==='respawn_wait'){if(msg.alive){notify('Ты уже в строю');return;}const remain=Math.max(0,Number(msg.remaining)||0);netRespawnAtClientMs=Date.now()+remain*1000;netAlive=false;document.querySelector('#netDeathOverlay')?.classList.add('show');updateNetworkDeathUI();return;}
 if(msg.type==='error'){setNetStatus('ОШИБКА');notify(String(msg.message||'Ошибка сервера'));return;}
 if(msg.type==='chat')notify(msg.nickname+': '+msg.text);
}
function disconnectMultiplayer(manual=false){if(netSocket){const ws=netSocket;netSocket=null;try{ws.close()}catch{}}netSelfId=null;netHostId=null;networkMapSeed=0;appliedRoomMap=null;appliedRoomMapSeed=null;updateMapAuthority();clearNetworkDeath();for(const e of remotePlayers.values())cleanupRemote(e);remotePlayers.clear();setNetStatus('НЕ ПОДКЛЮЧЕНО');updateNetRoster([]);if(manual)notify('Отключено от сетевой комнаты');}
document.querySelector('#multiplayerBtn')?.addEventListener('click',()=>{const name=document.querySelector('#playerNick')?.value?.trim()||'';document.querySelector('#netNick').value=netNickname||name;const a=document.querySelector('#netAddress');if(a&&(!a.value||a.value==='ws://localhost:8000')){const host=location.hostname||'localhost';a.value=(location.protocol==='https:'?'wss://':'ws://')+host+':8000';}document.querySelector('#multiplayerModal').classList.add('show');});
document.querySelector('#closeMultiplayer')?.addEventListener('click',()=>document.querySelector('#multiplayerModal').classList.remove('show'));
document.querySelector('#netConnect')?.addEventListener('click',()=>{const addr=document.querySelector('#netAddress').value.trim(),nickname=(document.querySelector('#netNick').value||document.querySelector('#playerNick')?.value||'Tanker').trim().slice(0,24),room=(document.querySelector('#netRoom').value||'POLYGON').trim().toUpperCase();if(!addr){notify('Укажи адрес WebSocket-сервера');return}if(netSocket)disconnectMultiplayer(false);try{setNetStatus('ПОДКЛЮЧЕНИЕ…');const ws=new WebSocket(addr);netSocket=ws;ws.onopen=()=>{netNickname=nickname||'Tanker';netRoomCode=room||'POLYGON';ws.send(JSON.stringify({type:'join',protocol:'armor-lab-v1',nickname:netNickname,room:netRoomCode,tank:selectedTank,map:document.querySelector('#mapSelect').value,config:collectRoomConfig()}));setNetStatus('ПОДКЛЮЧЕНИЕ К КОМНАТЕ…')};ws.onmessage=e=>{try{handleNetworkMessage(JSON.parse(e.data))}catch(err){console.error('ARMOR LAB network message error',err)}};ws.onerror=()=>{setNetStatus('ОШИБКА СОЕДИНЕНИЯ');notify('Не удалось подключиться. Проверь адрес и запущен ли сервер.');};ws.onclose=()=>{if(netSocket===ws){netSocket=null;netSelfId=null;netHostId=null;networkMapSeed=0;appliedRoomMap=null;appliedRoomMapSeed=null;updateMapAuthority();for(const e of remotePlayers.values())cleanupRemote(e);remotePlayers.clear();setNetStatus('НЕ ПОДКЛЮЧЕНО');updateNetRoster([]);}};}catch(e){setNetStatus('НЕВЕРНЫЙ АДРЕС');}});
